-- docs/migrations/011_expansion_ruta_completa.sql
--
-- Expande la Ruta Dariana de 10 a 60 sitios que otorgan sello:
-- 49 sitios extraídos de src/data/sitios.js (27 con su position tal cual,
-- ya de alta precisión; 22 con coordenadas verificadas contra Google Maps
-- en esta sesión, que reemplazan la de sitios.js) + Puerto Salvador Allende
-- (Managua), agregado fuera de la lista original como sitio de prueba para
-- el hackathon. Quedan fuera, sin tocar: ids 32,33,34,37,42,43,63,83,97
-- (no verificables aún; se ven en otra sesión).
--
-- insignia.nombre para los 49 nuevos (y para Puerto Salvador Allende): se usó
-- el mismo sitio.nombre completo (no un nombre genérico de icono como los 10
-- originales -- cathedral/territory/guitar/etc. -- porque cada badge nuevo es
-- un slug específico del sitio, no un arquetipo reutilizable). Puerto
-- Salvador Allende tiene insignia propia 'puerto_salvador_allende' (ya no
-- reutiliza la clave 'territory' de Ruinas de León Viejo como placeholder).

begin;

