-- 2. Sitios nuevos (49), resolviendo insignia_id por join a la clave recién
--    insertada (evita RETURNING/variables para 49 filas).
insert into public.sitio (id, insignia_id, nombre, descripcion_corta, historia, latitud, longitud, radio_sello_metros)
select v.id, i.id, v.nombre, v.descripcion_corta, v.historia, v.latitud, v.longitud, v.radio_sello_metros
from (values
  (11, 'casa_museo_y_archivo_ruben_dario', 'Casa Museo y Archivo Rubén Darío', 'Casa de infancia del poeta; hoy museo y archivo.', 'Casa Museo y Archivo Rubén Darío es la parada principal del circuito dariano en León y ocupa la casa solariega conocida como Las Cuatro Esquinas, donde Félix Rubén García Sarmiento vivió desde sus primeros días de vida hasta los 14 años. El museo fue creado por iniciativa del doctor Edgardo Buitrago e inaugurado en 1964; conserva espacios de la vivienda, objetos personales, documentos, manuscritos y una biblioteca especializada que permite reconstruir la infancia, formación y trayectoria del poeta. La importancia del lugar no depende únicamente de su relación con Darío: también muestra cómo era una casa leonesa de tradición colonial y cómo la arquitectura doméstica se convirtió en patrimonio cultural. Por ello funciona a la vez como museo literario, archivo histórico y punto de partida para comprender la identidad de León como ciudad de poetas. Casa de infancia del poeta; hoy museo y archivo.', 12.434871, -86.882862, 30),
  (12, 'estatua_de_ruben_dario_colegio_la_salle', 'Estatua de Rubén Darío - Colegio La Salle', 'Hito escultórico de la ruta relacionado con la memoria pública de Darío.', 'Estatua de Rubén Darío - Colegio La Salle es un punto de interés dentro del patrimonio leonés. Dentro del circuito dariano de León, este sitio adquiere valor por su relación directa o simbólica con la vida, educación, obra y memoria pública de Rubén Darío. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Hito escultórico de la ruta relacionado con la memoria pública de Darío.', 12.435439, -86.883345, 30),
  (14, 'hotel_el_convento_antiguo_lugar', 'Hotel El Convento / antiguo lugar vinculado a su infancia', 'Lugar relacionado con la formación y vida temprana del poeta.', 'Hotel El Convento / antiguo lugar vinculado a su infancia es un punto de interés dentro del patrimonio leonés. Dentro del circuito dariano de León, este sitio adquiere valor por su relación directa o simbólica con la vida, educación, obra y memoria pública de Rubén Darío. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Lugar relacionado con la formación y vida temprana del poeta.', 12.435732, -86.88164, 30),
  (16, 'parque_de_los_poetas', 'Parque de los Poetas', 'Espacio dedicado a la tradición literaria leonesa.', 'Parque de los Poetas es un punto de interés dentro del patrimonio leonés. Dentro del circuito dariano de León, este sitio adquiere valor por su relación directa o simbólica con la vida, educación, obra y memoria pública de Rubén Darío. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Espacio dedicado a la tradición literaria leonesa.', 12.437448, -86.880622, 30),
  (19, 'antigua_casa_de_salud_debayle', 'Antigua Casa de Salud Debayle', 'Debayle y a la vida intelectual de León.', 'Antigua Casa de Salud Debayle es un punto de interés dentro del patrimonio leonés. Dentro del circuito dariano de León, este sitio adquiere valor por su relación directa o simbólica con la vida, educación, obra y memoria pública de Rubén Darío. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Inmueble histórico vinculado al doctor Luis H. Debayle y a la vida intelectual de León.', 12.43416, -86.877396, 30),
  (21, 'plazoleta_ruben_dario', 'Plazoleta Rubén Darío', 'Espacio urbano con monumento al poeta en el Paseo de los Leones.', 'Plazoleta Rubén Darío es un punto de interés dentro del patrimonio leonés. Dentro del circuito dariano de León, este sitio adquiere valor por su relación directa o simbólica con la vida, educación, obra y memoria pública de Rubén Darío. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Espacio urbano con monumento al poeta en el Paseo de los Leones.', 12.422548, -86.872952, 80),
  (22, 'parque_centenario_ruben_dario', 'Parque Centenario Rubén Darío', 'Parque creado en 2016 para conmemorar el centenario de la muerte de Darío.', 'Parque Centenario Rubén Darío es un punto de interés dentro del patrimonio leonés. Dentro del circuito dariano de León, este sitio adquiere valor por su relación directa o simbólica con la vida, educación, obra y memoria pública de Rubén Darío. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Parque creado en 2016 para conmemorar el centenario de la muerte de Darío.', 12.417755, -86.869637, 80),
  (23, 'iglesia_la_merced', 'Iglesia La Merced', 'Santuario histórico y una de las fachadas más reconocibles de León.', 'Iglesia La Merced es un punto de interés dentro del patrimonio leonés. En el conjunto religioso de León, este templo o ruina forma parte del paisaje que hizo de la ciudad un referente del patrimonio colonial y de la tradición religiosa nicaragüense. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Santuario histórico y una de las fachadas más reconocibles de León.', 12.436486, -86.878989, 30),
  (24, 'iglesia_el_calvario', 'Iglesia El Calvario', 'Templo histórico de marcada presencia urbana y vínculo con la memoria de la ciudad.', 'Iglesia El Calvario es un punto de interés dentro del patrimonio leonés. En el conjunto religioso de León, este templo o ruina forma parte del paisaje que hizo de la ciudad un referente del patrimonio colonial y de la tradición religiosa nicaragüense. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Templo histórico de marcada presencia urbana y vínculo con la memoria de la ciudad.', 12.43179, -86.872782, 30),
  (45, 'museo_casa_natal_rigoberto_lopez_perez', 'Museo Casa Natal Rigoberto López Pérez', 'Casa natal y espacio de memoria del poeta y figura histórica de la ciudad.', 'Museo Casa Natal Rigoberto López Pérez es un punto de interés dentro del patrimonio leonés. Como espacio de memoria, investigación, exhibición o educación, este lugar contribuye a explicar la identidad histórica y cultural de León y de sus comunidades. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Casa natal y espacio de memoria del poeta y figura histórica de la ciudad.', 12.436139, -86.872808, 80),
  (46, 'centro_cultural_y_museo_rigoberto_lopez', 'Centro Cultural y Museo Rigoberto López Pérez', 'Antigua Casa del Obrero, hoy espacio museístico relacionado con la historia política de Nicaragua.', 'Centro Cultural y Museo Rigoberto López Pérez es un punto de interés dentro del patrimonio leonés. Como espacio de memoria, investigación, exhibición o educación, este lugar contribuye a explicar la identidad histórica y cultural de León y de sus comunidades. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Antigua Casa del Obrero, hoy espacio museístico relacionado con la historia política de Nicaragua.', 12.436583, -86.880774, 30),
  (47, 'museo_de_leyendas_y_tradiciones_coronel', 'Museo de Leyendas y Tradiciones Coronel Joaquín de Arrechavala', 'Museo instalado en el antiguo edificio de la cárcel conocida como La 21.', 'El Museo de Leyendas y Tradiciones Coronel Joaquín de Arrechavala ocupa el edificio de la antigua cárcel conocida como «La 21», un inmueble que adquirió un valor simbólico especialmente fuerte por los usos represivos que tuvo durante el siglo XX. El museo transforma ese pasado en un espacio de interpretación de las leyendas, tradiciones y personajes de León, y al mismo tiempo conserva la memoria física del edificio y de la historia política que lo rodea. Las salas presentan relatos y elementos de la cultura popular, mientras algunas áreas explican las condiciones y formas de tortura asociadas al antiguo presidio. Su interés turístico está, precisamente, en esa doble lectura: por un lado, patrimonio material de la ciudad y, por otro, memoria social. Es uno de los lugares donde la cultura oral, la historia política y la arquitectura histórica se encuentran en un mismo recorrido. Museo instalado en el antiguo edificio de la cárcel conocida como La 21.', 12.432011, -86.878846, 80),
  (48, 'museo_entomologico', 'Museo Entomológico', 'Colección científica y educativa que forma parte del patrimonio cultural y académico de León.', 'Museo Entomológico es un punto de interés dentro del patrimonio leonés. Como espacio de memoria, investigación, exhibición o educación, este lugar contribuye a explicar la identidad histórica y cultural de León y de sus comunidades. Los inventarios y guías consultados lo relacionan con el tejido histórico de la ciudad, ya sea por su arquitectura, por los acontecimientos que se desarrollaron en el lugar o por su función cultural. Su valor se entiende mejor al observarlo dentro del conjunto urbano: calles, plazas, templos, viviendas, instituciones y espacios de memoria forman una red que conserva distintas capas de la historia de León, desde la época colonial y republicana hasta la vida intelectual, universitaria y política del siglo XX. Más que un edificio aislado, este sitio funciona como evidencia de cómo la sociedad leonesa construyó su identidad y cómo esa identidad sigue presente en el patrimonio material y en las prácticas culturales actuales. Colección científica y educativa que forma parte del patrimonio cultural y académico de León.', 12.434754, -86.871226, 80),
  (49, 'centro_de_arte_fundacion_ortiz_gurdian', 'Centro de Arte Fundación Ortiz-Gurdián', 'Conjunto de casas patrimoniales convertido en importante espacio de arte y cultura.', 'El Centro de Arte Fundación Ortiz-Gurdián ocupa varias casas patrimoniales del centro histórico de León y combina conservación arquitectónica con exhibición de arte. El conjunto es importante porque muestra cómo la vivienda tradicional leonesa puede adaptarse a un uso cultural contemporáneo sin perder la lectura de sus patios, corredores, proporciones y materiales. Las casas Norberto Ramírez y Derbyshire, entre otras, forman parte del circuito y ayudan a explicar la evolución de la arquitectura doméstica de la ciudad durante los siglos XIX y XX. Además, el centro se convirtió en uno de los espacios artísticos más reconocidos de León, vinculando patrimonio construido y patrimonio artístico. Esta integración entre arquitectura histórica, exposiciones y actividades culturales es una de las razones por las que el centro ocupa un lugar destacado dentro del turismo cultural leonés. Conjunto de casas patrimoniales convertido en importante espacio de arte y cultura.', 12.43471, -86.881941, 30),
