-- 3. Puerto Salvador Allende (Managua) -- fuera de la lista original,
--    con insignia propia 'puerto_salvador_allende' (ya no reutiliza
--    'territory' como placeholder).
insert into public.sitio (id, insignia_id, nombre, descripcion_corta, historia, latitud, longitud, radio_sello_metros)
values (
  98,
  (select id from public.insignia where clave = 'puerto_salvador_allende'),
  'Puerto Salvador Allende',
  'Malecón turístico sobre el Lago Xolotlán, en Managua, con restaurantes, paseos en bote y vista al volcán Momotombo.',
  'El Puerto Salvador Allende está en la orilla sur del Lago Xolotlán (Lago de Managua), en el antiguo centro de la capital, cerca del Teatro Nacional Rubén Darío y la vieja Catedral de Managua. Lleva el nombre del expresidente chileno Salvador Allende y se desarrolló como un malecón moderno con restaurantes, kioscos y paseos en bote hacia la Isla del Amor, desde donde se aprecia el volcán Momotombo al otro lado del lago.',
  12.164023,
  -86.278134,
  80
);

-- 4. Corrección de radio en 3 sitios YA EXISTENTES (no se tocan sus demás
--    columnas): ahora tienen un vecino nuevo a menos de 150m.
--    id1 (Catedral de León) a 30m del Palacio Episcopal (id59); id5
--    (Iglesia San Juan Bautista) a 87.9m de id74 (Casa de la Familia
--    Lacayo/Hotel La Perla); id7 (Teatro Municipal) a 120.4m de id27
--    (Iglesia San Juan de Dios).
update public.sitio set radio_sello_metros = 30 where id in (1, 5, 7);

-- 5. Reajustar las secuencias identity para que el próximo insert
--    automático no choque con los ids explícitos insertados arriba.
select setval(pg_get_serial_sequence('sitio','id'), (select max(id) from public.sitio));
select setval(pg_get_serial_sequence('insignia','id'), (select max(id) from public.insignia));

commit;
